import { Logger, NotFoundException } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';

/**
 * The health of an inbox, derived from the warm up reputation reported by
 * smartlead. Anything below `LOW_DELIVERABILITY_SCORE` is considered burned and
 * should not be used for a campaign.
 */
export enum DeliverabilityScore {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

export const HIGH_DELIVERABILITY_SCORE = 100;
export const MEDIUM_DELIVERABILITY_SCORE = 98;
export const LOW_DELIVERABILITY_SCORE = 95;

/**
 * Defaults documented in the campaign playbook, a campaign runs for 10 days and
 * every inbox sends 20 emails a day.
 */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;

export const SMARTLEAD_EMAIL_ACCOUNTS_URL =
  'https://server.smartlead.ai/api/v1/email-accounts';

/**
 * The shape of an inbox as returned by the smartlead email-accounts api.
 * See: https://server.smartlead.ai/api/v1/email-accounts/
 */
export type SmartleadInbox = {
  smartleadInboxId: string;
  email?: string;
  smartleadClientId?: string;
  createdAt?: string;
  warmupReputation?: number;
};

/**
 * An email account (inbox) which has been warmed up inside of smartlead and can
 * be associated with one or more campaigns.
 *
 * The inbox is keyed by its smartlead inbox id, which is the id smartlead uses
 * for the email account inside of their api.
 */
export class EmailAccount {
  private static readonly logger = new Logger(EmailAccount.name);
  smartleadInboxId: string;
  email: string;
  smartleadClientId: string;
  domain: string;
  tags: string[];
  campaignIds: string[];
  numberOfCampaignAssociated: number;
  warmupReputation?: number;
  deliverabilityScore: DeliverabilityScore;
  createdAt?: string;
  updatedAt?: string;

  constructor(partial: Partial<EmailAccount>) {
    Object.assign(this, partial);
    // The mongo datastore appends the collection it found the document in.
    //@ts-expect-error _collection is a datastore implementation detail
    if (this?._collection) {
      //@ts-expect-error _collection is a datastore implementation detail
      delete this._collection;
    }
    if (this.smartleadInboxId !== undefined && this.smartleadInboxId !== null) {
      this.smartleadInboxId = `${this.smartleadInboxId}`;
    }
    if (
      this.smartleadClientId !== undefined &&
      this.smartleadClientId !== null
    ) {
      this.smartleadClientId = `${this.smartleadClientId}`;
    }
    this.tags = EmailAccount.toUniqueList(this.tags);
    this.campaignIds = EmailAccount.toUniqueList(this.campaignIds);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    this.domain = EmailAccount.getDomain(this.email);
    this.warmupReputation = EmailAccount.parseWarmupReputation(
      this.warmupReputation,
    );
    this.deliverabilityScore = EmailAccount.getDeliverabilityScore(
      this.warmupReputation,
    );
  }

  private static toUniqueList(list?: string[]): string[] {
    if (!list || !Array.isArray(list)) {
      return [];
    }
    return list.filter(
      (item, index) => item !== undefined && item !== null && list.indexOf(item) === index,
    );
  }

  /**
   * The domain of the inbox, derived from the email address. Inboxes which
   * share a domain share a reputation, so we prefer to spread a campaign over
   * as many domains as possible.
   */
  static getDomain(email?: string): string | undefined {
    if (!email || typeof email !== 'string' || !email.includes('@')) {
      return undefined;
    }
    const domain = email.split('@').pop();
    return domain ? domain.trim().toLowerCase() : undefined;
  }

  /**
   * Smartlead reports the warm up reputation as either a number or a
   * percentage string, ie: `100%`.
   */
  static parseWarmupReputation(
    warmupReputation?: number | string,
  ): number | undefined {
    if (warmupReputation === undefined || warmupReputation === null) {
      return undefined;
    }
    if (typeof warmupReputation === 'number') {
      return Number.isFinite(warmupReputation) ? warmupReputation : undefined;
    }
    const parsed = parseFloat(`${warmupReputation}`.replace('%', ''));
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  /**
   * Maps the numeric deliverability (warm up reputation) score reported by
   * smartlead onto a deliverability bucket.
   */
  static getDeliverabilityScore(
    warmupReputation?: number | string,
  ): DeliverabilityScore {
    const score = EmailAccount.parseWarmupReputation(warmupReputation);
    if (score === undefined) {
      return DeliverabilityScore.Unknown;
    }
    if (score >= HIGH_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.High;
    }
    if (score >= MEDIUM_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.Medium;
    }
    if (score >= LOW_DELIVERABILITY_SCORE) {
      return DeliverabilityScore.Low;
    }
    return DeliverabilityScore.Burned;
  }

  static mapEmailAccount(item: any): EmailAccount {
    if (item?.data) {
      return new EmailAccount(item.data);
    }
    return new EmailAccount(item);
  }

  /**
   * Associates the inbox with a campaign. Associating the same campaign twice
   * is a no-op, so the caller can safely retry.
   */
  associateWithCampaign(campaignId: string): boolean {
    if (!campaignId) {
      return false;
    }
    if (this.campaignIds.includes(campaignId)) {
      return false;
    }
    this.campaignIds = [...this.campaignIds, campaignId];
    this.numberOfCampaignAssociated = this.campaignIds.length;
    return true;
  }

  addTags(tags?: string[]): string[] {
    this.tags = EmailAccount.toUniqueList([...this.tags, ...(tags || [])]);
    return this.tags;
  }

  async save(datastoreService: DatastoreService): Promise<EmailAccount> {
    if (!this.smartleadInboxId) {
      throw new NotFoundException('Email account is missing a smartleadInboxId');
    }
    this.createdAt = this.createdAt ? this.createdAt : new Date().toISOString();
    this.updatedAt = new Date().toISOString();
    EmailAccount.logger.log(
      `Saving email account: ${this.email} inbox: ${this.smartleadInboxId}`,
    );
    await datastoreService.store(
      new StoreDataDto({
        data: { ...this },
        context: {
          uniqueId: this.smartleadInboxId,
          documentType: documentType.EMAIL_ACCOUNT,
        },
      }),
    );
    return this;
  }

  async delete(
    datastoreService: DatastoreService,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    EmailAccount.logger.log(
      `Deleting email account inbox: ${this.smartleadInboxId}`,
    );
    await datastoreService.remove({
      id: this.smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return {
      message: 'Email account deleted successfully',
      smartleadInboxId: this.smartleadInboxId,
    };
  }

  private static async findByField(
    fieldKey: string,
    fieldValue: string | Record<string, any>,
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    const res = await datastoreService.getByField({
      fieldKey,
      fieldValue,
      documentType: documentType.EMAIL_ACCOUNT,
      ...(pagination ? { pagination } : {}),
    });
    if (!res?.data || res.data.length === 0) {
      return [];
    }
    return res.data.map(EmailAccount.mapEmailAccount);
  }

  static async findBySmartleadInboxId(
    smartleadInboxId: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount | undefined> {
    const emailAccounts = await EmailAccount.findByField(
      'data.smartleadInboxId',
      `${smartleadInboxId}`,
      datastoreService,
    );
    return emailAccounts[0];
  }

  static async findByEmail(
    email: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount | undefined> {
    const emailAccounts = await EmailAccount.findByField(
      'data.email',
      email,
      datastoreService,
    );
    return emailAccounts[0];
  }

  static async findBySmartleadClientId(
    smartleadClientId: string,
    datastoreService: DatastoreService,
  ): Promise<EmailAccount[]> {
    return EmailAccount.findByField(
      'data.smartleadClientId',
      `${smartleadClientId}`,
      datastoreService,
    );
  }

  static async findAll(
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    return EmailAccount.findByField(
      'data.smartleadInboxId',
      { $exists: true },
      datastoreService,
      pagination,
    );
  }

  /**
   * The number of inboxes required to send `totalNumberOfEmailsToSend` emails
   * over the length of the campaign.
   *
   * Example: 500 emails, over 10 days, at 20 emails per inbox per day requires
   * 2 inboxes.
   */
  static getRequiredNumberOfInboxes({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const days = numberOfDaysInCampaign
      ? numberOfDaysInCampaign
      : DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const emailsPerInboxPerDay = numberOfEmailsPerInboxPerDay
      ? numberOfEmailsPerInboxPerDay
      : DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    if (!totalNumberOfEmailsToSend || totalNumberOfEmailsToSend <= 0) {
      return 0;
    }
    return Math.floor(totalNumberOfEmailsToSend / days / emailsPerInboxPerDay);
  }

  /**
   * Ranks the inboxes so the healthiest, least used inboxes are used first.
   *
   * 1. Deliverability score, descending.
   * 2. Number of campaigns already associated, ascending.
   * 3. Number of other inboxes sharing the same domain, ascending.
   * 4. Creation time, oldest (most warmed up) first.
   */
  static rankInboxes(emailAccounts: EmailAccount[]): EmailAccount[] {
    if (!emailAccounts || emailAccounts.length === 0) {
      return [];
    }
    const inboxesPerDomain = emailAccounts.reduce<Record<string, number>>(
      (acc, emailAccount) => {
        const domain = emailAccount?.domain;
        if (domain) {
          acc[domain] = (acc[domain] || 0) + 1;
        }
        return acc;
      },
      {},
    );
    const otherInboxesOnDomain = (emailAccount: EmailAccount) =>
      emailAccount?.domain ? inboxesPerDomain[emailAccount.domain] - 1 : 0;

    return [...emailAccounts].sort((a, b) => {
      const scoreDifference =
        EmailAccount.getRankableWarmupReputation(b) -
        EmailAccount.getRankableWarmupReputation(a);
      if (scoreDifference !== 0) {
        return scoreDifference;
      }
      const campaignDifference =
        (a?.numberOfCampaignAssociated || 0) -
        (b?.numberOfCampaignAssociated || 0);
      if (campaignDifference !== 0) {
        return campaignDifference;
      }
      const domainDifference =
        otherInboxesOnDomain(a) - otherInboxesOnDomain(b);
      if (domainDifference !== 0) {
        return domainDifference;
      }
      return (
        EmailAccount.getRankableCreatedAt(a) -
        EmailAccount.getRankableCreatedAt(b)
      );
    });
  }

  private static getRankableWarmupReputation(emailAccount: EmailAccount) {
    const score = EmailAccount.parseWarmupReputation(
      emailAccount?.warmupReputation,
    );
    // An inbox with an unknown reputation is ranked below a burned inbox.
    return score === undefined ? -1 : score;
  }

  private static getRankableCreatedAt(emailAccount: EmailAccount) {
    const createdAt = new Date(emailAccount?.createdAt).getTime();
    // Inboxes without a creation time are ranked last.
    return Number.isFinite(createdAt) ? createdAt : Number.MAX_SAFE_INTEGER;
  }

  /**
   * Reads an inbox from smartlead so we can hydrate the creation time and the
   * warm up reputation of the inbox.
   */
  static async fetchSmartleadInbox({
    smartleadInboxId,
    email,
  }: {
    smartleadInboxId?: string;
    email?: string;
  }): Promise<SmartleadInbox> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    let rawInbox: any;
    if (smartleadInboxId) {
      rawInbox = await EmailAccount.fetchJson(
        `${SMARTLEAD_EMAIL_ACCOUNTS_URL}/${smartleadInboxId}?api_key=${apiKey}`,
      );
    }
    if (!EmailAccount.isSmartleadInbox(rawInbox)) {
      // Fall back to the list endpoint, which is also the only way to look an
      // inbox up by email address.
      const rawInboxes = await EmailAccount.fetchJson(
        `${SMARTLEAD_EMAIL_ACCOUNTS_URL}/?api_key=${apiKey}&offset=0&limit=1000`,
      );
      rawInbox = Array.isArray(rawInboxes)
        ? rawInboxes.find(
            (inbox) =>
              (smartleadInboxId &&
                `${inbox?.id}` === `${smartleadInboxId}`) ||
              (email &&
                `${inbox?.from_email}`.toLowerCase() ===
                  `${email}`.toLowerCase()),
          )
        : undefined;
    }
    if (!EmailAccount.isSmartleadInbox(rawInbox)) {
      EmailAccount.logger.error(
        `Email account not found in smartlead. inbox: ${smartleadInboxId} email: ${email}`,
      );
      throw new NotFoundException('Email account not found in smartlead');
    }
    return {
      smartleadInboxId: `${rawInbox.id}`,
      email: rawInbox?.from_email ? rawInbox.from_email : email,
      smartleadClientId:
        rawInbox?.client_id !== undefined && rawInbox?.client_id !== null
          ? `${rawInbox.client_id}`
          : undefined,
      createdAt: rawInbox?.created_at ? rawInbox.created_at : undefined,
      warmupReputation: EmailAccount.parseWarmupReputation(
        rawInbox?.warmup_details?.warmup_reputation !== undefined
          ? rawInbox.warmup_details.warmup_reputation
          : rawInbox?.warmup_reputation,
      ),
    };
  }

  private static isSmartleadInbox(rawInbox: any): boolean {
    return Boolean(
      rawInbox && !Array.isArray(rawInbox) && rawInbox?.id !== undefined,
    );
  }

  private static async fetchJson(url: string): Promise<any> {
    try {
      const res = await fetch(url);
      if (!res?.ok) {
        EmailAccount.logger.warn(
          `Smartlead email account request failed with status: ${res?.status}`,
        );
        return undefined;
      }
      return await res.json();
    } catch (error) {
      EmailAccount.logger.error(
        `Error reading email account from smartlead: ${error}`,
      );
      return undefined;
    }
  }
}

import { IsArray, IsNumber, IsOptional, IsString } from 'class-validator';

export class EmailAccountDto {
  /**
   * The id smartlead uses for the inbox. This is the key of an email account.
   */
  @IsOptional()
  @IsString()
  smartleadInboxId?: string;
  @IsString()
  email: string;
  @IsString()
  smartleadClientId: string;
  @IsOptional()
  @IsArray()
  tags?: string[];
  @IsOptional()
  @IsArray()
  campaignIds?: string[];
}

export class EmailAccountListDto {
  totalNumberOfEmailsToSend: number;
  smartleadClientId: string;
  campaignId: string;
  numberOfDaysInCampaign?: number;
  numberOfEmailsPerInboxPerDay?: number;
}

export class AssociateEmailAccountsWithCampaignDto {
  @IsArray()
  emailAccountIds: string[];
  @IsString()
  campaignId: string;
}

export class ReadEmailAccountsDto {
  @IsOptional()
  @IsNumber()
  page?: number;
  @IsOptional()
  @IsNumber()
  pageSize?: number;
  @IsOptional()
  @IsString()
  smartleadClientId?: string;
}

export { DeliverabilityScore } from '../entities/emailAccount.entity';

import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import {
  EmailAccountDto,
  EmailAccountListDto,
  ReadEmailAccountsDto,
} from './dto/emailAccount.dto';
import { DatastoreService } from '../datastore/datastore.service';
import { EmailAccount } from './entities/emailAccount.entity';

export const DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE = 100;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  /**
   * The datastore is optional so the service can be constructed in isolation,
   * ie: by the import / reputation sync scripts and by unit tests.
   */
  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
  ) {}

  /**
   * Returns the best inboxes to use for a campaign.
   *
   * The number of inboxes needed is the total number of emails we want to send,
   * divided by the length of the campaign, divided by the number of emails a
   * single inbox sends per day.
   *
   * Example:
   *  500 emails to send
   *  10 days in the campaign
   *  20 emails per day per inbox
   *  => the top 2 inboxes of the client are returned.
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign,
    numberOfEmailsPerInboxPerDay,
    totalNumberOfEmailsToSend,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const requiredNumberOfInboxes = EmailAccount.getRequiredNumberOfInboxes({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Getting the best ${requiredNumberOfInboxes} email accounts for campaign: ${campaignId} client: ${smartleadClientId}`,
    );
    if (requiredNumberOfInboxes <= 0) {
      return [];
    }
    const emailAccounts = await EmailAccount.findBySmartleadClientId(
      smartleadClientId,
      this.getDatastoreService(),
    );
    this.logger.log(
      `Found ${emailAccounts.length} email accounts for client: ${smartleadClientId}`,
    );
    return EmailAccount.rankInboxes(emailAccounts).slice(
      0,
      requiredNumberOfInboxes,
    );
  }

  /**
   * Associates a list of inboxes with a campaign. Associating an inbox which is
   * already associated with the campaign is a no-op, so the request can safely
   * be retried. If any of the requested inboxes do not exist the whole request
   * is rejected.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: {
    emailAccountIds: string[];
    campaignId: string;
  }): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    if (!emailAccountIds || emailAccountIds.length === 0) {
      throw new BadRequestException('emailAccountIds is required');
    }
    this.logger.log(
      `Associating email accounts: ${emailAccountIds.join(', ')} with campaign: ${campaignId}`,
    );
    const emailAccounts = await Promise.all(
      emailAccountIds.map(async (smartleadInboxId) => ({
        smartleadInboxId,
        emailAccount: await EmailAccount.findBySmartleadInboxId(
          smartleadInboxId,
          this.getDatastoreService(),
        ),
      })),
    );
    const missingEmailAccountIds = emailAccounts
      .filter(({ emailAccount }) => !emailAccount)
      .map(({ smartleadInboxId }) => smartleadInboxId);
    if (missingEmailAccountIds.length > 0) {
      this.logger.error(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
      throw new NotFoundException(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
    }
    return Promise.all(
      emailAccounts.map(async ({ emailAccount }) => {
        const associated = emailAccount.associateWithCampaign(campaignId);
        if (!associated) {
          this.logger.log(
            `Email account: ${emailAccount.smartleadInboxId} is already associated with campaign: ${campaignId}`,
          );
          return emailAccount;
        }
        return emailAccount.save(this.getDatastoreService());
      }),
    );
  }

  /**
   * Saves an inbox, hydrating the creation time and the warm up reputation of
   * the inbox from smartlead.
   */
  async saveEmailAccount(
    emailAccountDto: EmailAccountDto,
  ): Promise<EmailAccount> {
    if (!emailAccountDto?.smartleadInboxId && !emailAccountDto?.email) {
      throw new BadRequestException(
        'smartleadInboxId or email is required to save an email account',
      );
    }
    const smartleadInbox = await EmailAccount.fetchSmartleadInbox({
      smartleadInboxId: emailAccountDto?.smartleadInboxId,
      email: emailAccountDto?.email,
    });
    const existingEmailAccount = await EmailAccount.findBySmartleadInboxId(
      smartleadInbox.smartleadInboxId,
      this.getDatastoreService(),
    );
    const emailAccount = new EmailAccount({
      ...(existingEmailAccount ? existingEmailAccount : {}),
      ...emailAccountDto,
      smartleadInboxId: smartleadInbox.smartleadInboxId,
      email: emailAccountDto?.email ? emailAccountDto.email : smartleadInbox.email,
      smartleadClientId: emailAccountDto?.smartleadClientId
        ? emailAccountDto.smartleadClientId
        : smartleadInbox.smartleadClientId,
      createdAt: smartleadInbox?.createdAt
        ? smartleadInbox.createdAt
        : existingEmailAccount?.createdAt,
      warmupReputation: smartleadInbox?.warmupReputation,
    });
    return emailAccount.save(this.getDatastoreService());
  }

  /**
   * Reads an inbox by its smartlead inbox id, or by its email address.
   */
  async getEmailAccount(
    emailAccount: EmailAccountDto | string,
  ): Promise<EmailAccount> {
    const smartleadInboxId =
      typeof emailAccount === 'string'
        ? emailAccount
        : emailAccount?.smartleadInboxId;
    const email =
      typeof emailAccount === 'string' ? undefined : emailAccount?.email;
    if (!smartleadInboxId && !email) {
      throw new BadRequestException(
        'smartleadInboxId or email is required to read an email account',
      );
    }
    const foundEmailAccount = smartleadInboxId
      ? await EmailAccount.findBySmartleadInboxId(
          smartleadInboxId,
          this.getDatastoreService(),
        )
      : await EmailAccount.findByEmail(email, this.getDatastoreService());
    if (!foundEmailAccount) {
      throw new NotFoundException('Email account not found');
    }
    return foundEmailAccount;
  }

  /**
   * Reads all of the inboxes, a page at a time.
   */
  async getAllEmailAccounts(
    readEmailAccountsDto?: ReadEmailAccountsDto,
  ): Promise<EmailAccount[]> {
    const { page, pageSize, smartleadClientId } = readEmailAccountsDto
      ? readEmailAccountsDto
      : ({} as ReadEmailAccountsDto);
    if (smartleadClientId) {
      return this.getEmailAccountBySmartleadClientId(smartleadClientId);
    }
    const pagination =
      page !== undefined || pageSize !== undefined
        ? {
            page: page ? Number(page) : 0,
            pageSize: pageSize
              ? Number(pageSize)
              : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
          }
        : undefined;
    this.logger.log(
      `Getting all email accounts. page: ${pagination?.page} pageSize: ${pagination?.pageSize}`,
    );
    return EmailAccount.findAll(this.getDatastoreService(), pagination);
  }

  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    if (!email) {
      throw new BadRequestException('email is required');
    }
    const emailAccount = await EmailAccount.findByEmail(
      email,
      this.getDatastoreService(),
    );
    if (!emailAccount) {
      throw new NotFoundException('Email account not found');
    }
    return emailAccount;
  }

  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    return EmailAccount.findBySmartleadClientId(
      smartleadClientId,
      this.getDatastoreService(),
    );
  }

  async deleteEmailAccount(
    emailAccount: EmailAccountDto | string,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    const foundEmailAccount = await this.getEmailAccount(emailAccount);
    return foundEmailAccount.delete(this.getDatastoreService());
  }

  private getDatastoreService(): DatastoreService {
    if (!this.datastoreService) {
      throw new BadRequestException('No datastore configured');
    }
    return this.datastoreService;
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-account')
  saveEmailAccount(@Body() emailAccountDto: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(emailAccountDto);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-accounts')
  getAllEmailAccounts(
    @Query('page') page?: number,
    @Query('pageSize') pageSize?: number,
    @Query('smartleadClientId') smartleadClientId?: string,
  ) {
    return this.emailinfraService.getAllEmailAccounts({
      page,
      pageSize,
      smartleadClientId,
    });
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account/by-email')
  getEmailAccountByEmail(@Query('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('/email-account/:smartleadInboxId')
  getEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Delete('/email-account/:smartleadInboxId')
  deleteEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-accounts/associate')
  associateEmailAccountsWithCampaign(
    @Body()
    associateEmailAccountsWithCampaignDto: AssociateEmailAccountsWithCampaignDto,
  ) {
    return this.emailinfraService.associateEmailAccountsWithCampaign(
      associateEmailAccountsWithCampaignDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('/email-accounts/best')
  getBestEmailAccountsForCampaign(
    @Body() emailAccountListDto: EmailAccountListDto,
  ) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountListDto,
    );
  }
}

