import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraModule } from './emailinfra.module';
import { DatastoreService } from '../datastore/datastore.service';
import {
  DeliverabilityScore,
  EmailAccount,
} from './entities/emailAccount.entity';

/**
 * An in memory stand in for the datastore, it mirrors the mongo datastore in
 * that documents are stored as `{ id, data }` and read back by a `data.` field.
 */
class InMemoryDatastore {
  documents: Array<{ id: string; data: any }> = [];

  async store({ data, context }) {
    const existing = this.documents.find((doc) => doc.id === context.uniqueId);
    if (existing) {
      existing.data = data;
    } else {
      this.documents.push({ id: context.uniqueId, data });
    }
    return { message: 'Data stored successfully', uniqueId: context.uniqueId };
  }

  async getByField({ fieldKey, fieldValue, pagination }) {
    const key = fieldKey.replace('data.', '');
    let data = this.documents
      .filter((doc) =>
        fieldValue?.$exists
          ? doc.data[key] !== undefined
          : doc.data[key] === fieldValue,
      )
      .map((doc) => doc.data);
    if (pagination) {
      data = data.slice(
        pagination.page * pagination.pageSize,
        pagination.page * pagination.pageSize + pagination.pageSize,
      );
    }
    return { data: data.length > 0 ? data : undefined, message: 'ok' };
  }

  async remove({ id }) {
    this.documents = this.documents.filter((doc) => doc.id !== id);
    return { message: 'Data removed successfully' };
  }
}

const smartleadInbox = ({
  id,
  email,
  clientId = 22,
  warmupReputation = '100%',
  createdAt = '2024-01-01T00:00:00.000Z',
}: {
  id: number | string;
  email: string;
  clientId?: number;
  warmupReputation?: string | number;
  createdAt?: string;
}) => ({
  id,
  from_email: email,
  client_id: clientId,
  created_at: createdAt,
  warmup_details: { warmup_reputation: warmupReputation },
});

describe('EmailinfraService', () => {
  let service: EmailinfraService;
  let datastore: InMemoryDatastore;

  beforeEach(async () => {
    datastore = new InMemoryDatastore();
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EmailinfraService,
        { provide: DatastoreService, useValue: datastore },
      ],
    }).compile();

    service = module.get<EmailinfraService>(EmailinfraService);
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  const mockSmartlead = (inboxes: Array<Record<string, any>>) => {
    global.fetch = jest.fn(async (url: string) => {
      const match = `${url}`.match(/email-accounts\/(\d+)\?/);
      if (match) {
        const inbox = inboxes.find((i) => `${i.id}` === match[1]);
        return {
          ok: Boolean(inbox),
          status: inbox ? 200 : 404,
          json: async () => (inbox ? inbox : { message: 'not found' }),
        };
      }
      return { ok: true, status: 200, json: async () => inboxes };
    }) as any;
  };

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  it('should be resolvable from the emailinfra module', async () => {
    const module: TestingModule = await Test.createTestingModule({
      imports: [EmailinfraModule],
    }).compile();
    expect(module.get<EmailinfraService>(EmailinfraService)).toBeDefined();
  });

  describe('deliverability score', () => {
    it.each([
      [100, DeliverabilityScore.High],
      [99, DeliverabilityScore.Medium],
      [98, DeliverabilityScore.Medium],
      [97, DeliverabilityScore.Low],
      [95, DeliverabilityScore.Low],
      [94, DeliverabilityScore.Burned],
      [0, DeliverabilityScore.Burned],
    ])('maps a warm up reputation of %s to %s', (reputation, expected) => {
      expect(EmailAccount.getDeliverabilityScore(reputation)).toBe(expected);
      expect(
        new EmailAccount({
          smartleadInboxId: '1',
          email: 'a@b.com',
          warmupReputation: reputation,
        }).deliverabilityScore,
      ).toBe(expected);
    });

    it('maps a missing warm up reputation to unknown', () => {
      expect(EmailAccount.getDeliverabilityScore(undefined)).toBe(
        DeliverabilityScore.Unknown,
      );
      expect(
        new EmailAccount({ smartleadInboxId: '1', email: 'a@b.com' })
          .deliverabilityScore,
      ).toBe(DeliverabilityScore.Unknown);
    });
  });

  describe('saveEmailAccount', () => {
    it('hydrates the created at and warm up reputation from smartlead', async () => {
      mockSmartlead([
        smartleadInbox({
          id: 101,
          email: 'sender@warm.com',
          warmupReputation: '99%',
          createdAt: '2023-05-05T00:00:00.000Z',
        }),
      ]);
      const emailAccount = await service.saveEmailAccount({
        smartleadInboxId: '101',
        email: 'sender@warm.com',
        smartleadClientId: '22',
        tags: ['warmed'],
      });
      expect(emailAccount.smartleadInboxId).toBe('101');
      expect(emailAccount.domain).toBe('warm.com');
      expect(emailAccount.createdAt).toBe('2023-05-05T00:00:00.000Z');
      expect(emailAccount.warmupReputation).toBe(99);
      expect(emailAccount.deliverabilityScore).toBe(DeliverabilityScore.Medium);
      expect(emailAccount.tags).toEqual(['warmed']);
      expect(emailAccount.campaignIds).toEqual([]);
      expect(emailAccount.numberOfCampaignAssociated).toBe(0);
      expect(datastore.documents).toHaveLength(1);
      expect(datastore.documents[0].id).toBe('101');
    });

    it('throws a not found error when the inbox does not exist in smartlead', async () => {
      mockSmartlead([]);
      await expect(
        service.saveEmailAccount({
          smartleadInboxId: '404',
          email: 'missing@warm.com',
          smartleadClientId: '22',
        }),
      ).rejects.toBeInstanceOf(NotFoundException);
      expect(datastore.documents).toHaveLength(0);
    });

    it('keeps the campaigns of an existing inbox when it is saved again', async () => {
      mockSmartlead([smartleadInbox({ id: 101, email: 'sender@warm.com' })]);
      await service.saveEmailAccount({
        smartleadInboxId: '101',
        email: 'sender@warm.com',
        smartleadClientId: '22',
      });
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['101'],
        campaignId: 'campaign-1',
      });
      const emailAccount = await service.saveEmailAccount({
        smartleadInboxId: '101',
        email: 'sender@warm.com',
        smartleadClientId: '22',
      });
      expect(emailAccount.campaignIds).toEqual(['campaign-1']);
      expect(emailAccount.numberOfCampaignAssociated).toBe(1);
    });
  });

  describe('lookups', () => {
    beforeEach(async () => {
      mockSmartlead([
        smartleadInbox({ id: 1, email: 'one@warm.com' }),
        smartleadInbox({ id: 2, email: 'two@warm.com' }),
        smartleadInbox({ id: 3, email: 'three@cold.com', clientId: 44 }),
      ]);
      await service.saveEmailAccount({
        smartleadInboxId: '1',
        email: 'one@warm.com',
        smartleadClientId: '22',
      });
      await service.saveEmailAccount({
        smartleadInboxId: '2',
        email: 'two@warm.com',
        smartleadClientId: '22',
      });
      await service.saveEmailAccount({
        smartleadInboxId: '3',
        email: 'three@cold.com',
        smartleadClientId: '44',
      });
    });

    it('reads an inbox by id', async () => {
      const emailAccount = await service.getEmailAccount('2');
      expect(emailAccount.email).toBe('two@warm.com');
    });

    it('reads an inbox by email', async () => {
      const emailAccount = await service.getEmailAccountByEmail('one@warm.com');
      expect(emailAccount.smartleadInboxId).toBe('1');
    });

    it('reads the inboxes of a smartlead client', async () => {
      const emailAccounts =
        await service.getEmailAccountBySmartleadClientId('22');
      expect(emailAccounts.map((e) => e.smartleadInboxId)).toEqual(['1', '2']);
    });

    it('throws a not found error for an unknown inbox', async () => {
      await expect(service.getEmailAccount('99')).rejects.toBeInstanceOf(
        NotFoundException,
      );
    });

    it('lists the inboxes a page at a time', async () => {
      const firstPage = await service.getAllEmailAccounts({
        page: 0,
        pageSize: 2,
      });
      const secondPage = await service.getAllEmailAccounts({
        page: 1,
        pageSize: 2,
      });
      expect(firstPage.map((e) => e.smartleadInboxId)).toEqual(['1', '2']);
      expect(secondPage.map((e) => e.smartleadInboxId)).toEqual(['3']);
      expect(await service.getAllEmailAccounts()).toHaveLength(3);
    });

    it('deletes an inbox', async () => {
      await service.deleteEmailAccount('1');
      expect(datastore.documents.map((doc) => doc.id)).toEqual(['2', '3']);
      await expect(service.getEmailAccount('1')).rejects.toBeInstanceOf(
        NotFoundException,
      );
    });
  });

  describe('associateEmailAccountsWithCampaign', () => {
    beforeEach(async () => {
      mockSmartlead([smartleadInbox({ id: 1, email: 'one@warm.com' })]);
      await service.saveEmailAccount({
        smartleadInboxId: '1',
        email: 'one@warm.com',
        smartleadClientId: '22',
      });
    });

    it('is idempotent', async () => {
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1'],
        campaignId: 'campaign-1',
      });
      const [emailAccount] = await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1'],
        campaignId: 'campaign-1',
      });
      expect(emailAccount.campaignIds).toEqual(['campaign-1']);
      expect(emailAccount.numberOfCampaignAssociated).toBe(1);
    });

    it('rejects the request when one of the inboxes is missing', async () => {
      await expect(
        service.associateEmailAccountsWithCampaign({
          emailAccountIds: ['1', 'missing'],
          campaignId: 'campaign-1',
        }),
      ).rejects.toBeInstanceOf(NotFoundException);
      const emailAccount = await service.getEmailAccount('1');
      expect(emailAccount.campaignIds).toEqual([]);
    });
  });

  describe('getBestEmailAccountsForCampaign', () => {
    const inboxes: Array<Partial<EmailAccount>> = [
      {
        smartleadInboxId: 'burned',
        email: 'burned@one.com',
        smartleadClientId: '22',
        warmupReputation: 80,
        createdAt: '2020-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'unknown',
        email: 'unknown@two.com',
        smartleadClientId: '22',
        createdAt: '2020-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'busy',
        email: 'busy@three.com',
        smartleadClientId: '22',
        warmupReputation: 100,
        campaignIds: ['campaign-a', 'campaign-b'],
        createdAt: '2020-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'shared-domain-a',
        email: 'a@shared.com',
        smartleadClientId: '22',
        warmupReputation: 100,
        createdAt: '2020-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'shared-domain-b',
        email: 'b@shared.com',
        smartleadClientId: '22',
        warmupReputation: 100,
        createdAt: '2020-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'newest',
        email: 'newest@solo.com',
        smartleadClientId: '22',
        warmupReputation: 100,
        createdAt: '2024-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'oldest',
        email: 'oldest@alone.com',
        smartleadClientId: '22',
        warmupReputation: 100,
        createdAt: '2019-01-01T00:00:00.000Z',
      },
      {
        smartleadInboxId: 'other-client',
        email: 'other@client.com',
