/**
 * Imports the warmed up inboxes of a smartlead client into the email account
 * datastore.
 *
 * Usage:
 *   SMARTLEAD_REPORT_API_KEY=... API_KEY=... SMARTLEAD_CLIENT_ID=22 \
 *     node client/tools/importEmailAccounts.js
 */
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const API_URL = process.env.API_URL
  ? process.env.API_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;
const SMARTLEAD_API_KEY = process.env.SMARTLEAD_REPORT_API_KEY;
const SMARTLEAD_CLIENT_ID = process.env.SMARTLEAD_CLIENT_ID;
const TAGS = process.env.TAGS ? process.env.TAGS.split(',') : [];

const getSmartleadInboxes = async () => {
  const res = await fetch(
    `https://server.smartlead.ai/api/v1/email-accounts/?api_key=${SMARTLEAD_API_KEY}&offset=0&limit=1000`,
  );
  if (!res.ok) {
    throw new Error(`Smartlead API error: ${res.status} ${res.statusText}`);
  }
  const inboxes = await res.json();
  return inboxes.filter((inbox) =>
    SMARTLEAD_CLIENT_ID
      ? `${inbox.client_id}` === `${SMARTLEAD_CLIENT_ID}`
      : true,
  );
};

const saveEmailAccount = async (inbox) => {
  const body = {
    smartleadInboxId: `${inbox.id}`,
    email: inbox.from_email,
    smartleadClientId: `${inbox.client_id}`,
    tags: TAGS,
  };
  const res = await fetch(`${API_URL}/emailinfra/email-account`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    throw new Error(
      `API error for inbox ${inbox.id}: ${res.status} ${res.statusText}`,
    );
  }
  return res.json();
};

const main = async () => {
  if (!API_KEY || !SMARTLEAD_API_KEY) {
    throw new Error('API_KEY and SMARTLEAD_REPORT_API_KEY are required');
  }
  const inboxes = await getSmartleadInboxes();
  console.log(`Found ${inboxes.length} inboxes in smartlead`);
  let counter = 0;
  for (const inbox of inboxes) {
    const emailAccount = await saveEmailAccount(inbox);
    counter++;
    console.log(
      `Imported ${counter} of ${inboxes.length}: ${emailAccount.email} (${emailAccount.deliverabilityScore})`,
    );
  }
};

main()
  .then(() => {
    console.log('Done');
  })
  .catch((error) => {
    console.error(`Error importing email accounts: ${error?.message}`);
    process.exit(1);
  });

/**
 * Re-reads every stored inbox from smartlead so the warm up reputation, and
 * therefore the deliverability score, of the inbox is up to date.
 *
 * Usage:
 *   API_KEY=... node client/tools/syncEmailAccountReputation.js
 */
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const API_URL = process.env.API_URL
  ? process.env.API_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;
const SMARTLEAD_CLIENT_ID = process.env.SMARTLEAD_CLIENT_ID;
const PAGE_SIZE = process.env.PAGE_SIZE ? parseInt(process.env.PAGE_SIZE) : 100;

const headers = {
  'Content-Type': 'application/json',
  'X-API-KEY': API_KEY,
};

const getEmailAccounts = async (page) => {
  const query = SMARTLEAD_CLIENT_ID
    ? `smartleadClientId=${SMARTLEAD_CLIENT_ID}`
    : `page=${page}&pageSize=${PAGE_SIZE}`;
  const res = await fetch(`${API_URL}/emailinfra/email-accounts?${query}`, {
    headers,
  });
  if (!res.ok) {
    throw new Error(`API error: ${res.status} ${res.statusText}`);
  }
  return res.json();
};

const syncEmailAccount = async (emailAccount) => {
  const res = await fetch(`${API_URL}/emailinfra/email-account`, {
    method: 'POST',
    headers,
    body: JSON.stringify({
      smartleadInboxId: emailAccount.smartleadInboxId,
      email: emailAccount.email,
      smartleadClientId: emailAccount.smartleadClientId,
      tags: emailAccount.tags,
    }),
  });
  if (!res.ok) {
    throw new Error(
      `API error for inbox ${emailAccount.smartleadInboxId}: ${res.status} ${res.statusText}`,
    );
  }
  return res.json();
};

const main = async () => {
  if (!API_KEY) {
    throw new Error('API_KEY is required');
  }
  let page = 0;
  let emailAccounts = await getEmailAccounts(page);
  while (emailAccounts && emailAccounts.length > 0) {
    for (const emailAccount of emailAccounts) {
      const synced = await syncEmailAccount(emailAccount);
      console.log(
        `${synced.email}: ${synced.warmupReputation} => ${synced.deliverabilityScore}`,
      );
    }
    if (SMARTLEAD_CLIENT_ID || emailAccounts.length < PAGE_SIZE) {
      break;
    }
    page++;
    emailAccounts = await getEmailAccounts(page);
  }
};

main()
  .then(() => {
    console.log('Done');
  })
  .catch((error) => {
    console.error(`Error syncing email account reputation: ${error?.message}`);
    process.exit(1);
  });

